import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../providers/language_provider.dart';
import '../../providers/auth_provider.dart';
import '../business/business_screen.dart';
import '../personal/personal_screen.dart';
import 'dashboard_screen.dart';

class MainNavigation extends StatefulWidget { const MainNavigation({super.key}); @override State<MainNavigation> createState()=>_MainNavigationState(); }
class _MainNavigationState extends State<MainNavigation>{int _index=0;
 @override Widget build(BuildContext context){final s=context.watch<LanguageProvider>().strings;final pages=[const DashboardScreen(),const BusinessScreen(),const PersonalScreen(),const _ReportsPlaceholder(),const _ProfileScreen()];return Scaffold(body:IndexedStack(index:_index,children:pages),bottomNavigationBar:NavigationBar(selectedIndex:_index,onDestinationSelected:(v)=>setState(()=>_index=v),destinations:[NavigationDestination(icon:const Icon(Icons.home_outlined),selectedIcon:const Icon(Icons.home_rounded),label:s.t('home')),NavigationDestination(icon:const Icon(Icons.storefront_outlined),selectedIcon:const Icon(Icons.storefront),label:s.t('business')),NavigationDestination(icon:const Icon(Icons.people_outline),selectedIcon:const Icon(Icons.people),label:s.t('personal')),NavigationDestination(icon:const Icon(Icons.bar_chart_outlined),selectedIcon:const Icon(Icons.bar_chart),label:s.t('reports')),NavigationDestination(icon:const Icon(Icons.person_outline),selectedIcon:const Icon(Icons.person),label:s.t('profile'))]));}}
class _ReportsPlaceholder extends StatelessWidget{const _ReportsPlaceholder();@override Widget build(BuildContext context)=>const Scaffold(body:Center(child:Text('Reports will be available in the next phase.')));}
class _ProfileScreen extends StatelessWidget{const _ProfileScreen();@override Widget build(BuildContext context){final user=context.watch<HisaabAuthProvider>().user;final lang=context.watch<LanguageProvider>();final s=lang.strings;return Scaffold(appBar:AppBar(title:Text(s.t('profile'))),body:ListView(padding:const EdgeInsets.all(20),children:[CircleAvatar(radius:34,child:Text((user?.phoneNumber??'H').substring(0,1).toUpperCase())),const SizedBox(height:12),Center(child:Text(user?.phoneNumber??'Hisaab user',style:Theme.of(context).textTheme.titleLarge)),const SizedBox(height:24),ListTile(leading:const Icon(Icons.language),title:Text(s.t('language')),trailing:DropdownButton<String>(value:lang.locale,items:const [DropdownMenuItem(value:'en',child:Text('English')),DropdownMenuItem(value:'hi',child:Text('हिन्दी')),DropdownMenuItem(value:'mr',child:Text('मराठी'))],onChanged:(v){if(v!=null)lang.setLanguage(v);})),ListTile(leading:const Icon(Icons.logout,color:Colors.red),title:Text(s.t('logout')),onTap:()=>context.read<HisaabAuthProvider>().signOut())]));}}
